class TRPCBuilder<TParams extends PartialRootConfigTypes = object> {
  context<TNewContext extends object | ContextCallback>() {
    type $Context = TNewContext extends ContextCallback
      ? Unwrap<TNewContext>
      : TNewContext;

    type NextParams = Overwrite<
      TParams,
      {
        ctx: $Context;
